/* eslint-disable n/no-sync */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Memory = require( '@stdlib/wasm/memory' );
var Complex64Array = require( '@stdlib/array/complex64' );
var Float32Array = require( '@stdlib/array/float32' );
var EPS = require( '@stdlib/constants/float32/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var Module = require( './../lib' ).Module;


// VARIABLES //

// Pointers (i.e., byte offsets) for storing two vectors and a complex number (using generous gaps to avoid overlap):
var XPTR = 0;
var YPTR = 128;
var APTR = 256;


// FUNCTIONS //

/**
* Tests for element-wise approximate equality.
*
* @private
* @param {Object} t - test object
* @param {Collection} actual - actual values
* @param {Collection} expected - expected values
* @param {number} rtol - relative tolerance
*/
function isApprox( t, actual, expected, rtol ) {
	var delta;
	var tol;
	var i;

	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		if ( actual[ i ] === expected[ i ] ) {
			t.strictEqual( actual[ i ], expected[ i ], 'returns expected value' );
		} else {
			delta = abs( actual[ i ] - expected[ i ] );
			tol = rtol * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance. actual: '+actual[ i ]+'. expected: '+expected[ i ]+'. delta: '+delta+'. tol: '+tol+'.' );
		}
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Module, 'function', 'main export is a function' );
	t.end();
});

tape( 'a module instance has a `main` method which has an arity of 6', function test( t ) {
	var mem;
	var mod;

	mem = new Memory({
		'initial': 0
	});
	mod = new Module( mem );
	t.strictEqual( mod.main.length, 6, 'returns expected value' );
	t.end();
});

tape( 'a module instance has a `main` method which scales elements from `x` by `alpha` and adds the result to `y`', function test( t ) {
	var actualY;
	var viewY;
	var mem;
	var mod;
	var ye;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	mod.write( XPTR, new Complex64Array( [ 0.7, -0.8, -0.4, -0.7, -0.1, -0.9, 0.2, -0.8 ] ) );
	mod.write( YPTR, new Complex64Array( [ 0.6, -0.6, -0.9, 0.5, 0.7, -0.6, 0.1, -0.5 ] ) );
	mod.write( APTR, new Float32Array( [ 0.4, -0.7 ] ) );

	ye = new Float32Array( [ 0.32, -1.41, -1.55, 0.5, 0.03, -0.89, -0.38, -0.96 ] );

	mod.main( 4, APTR, XPTR, 1, YPTR, 1 );

	actualY = new Complex64Array( 4 );
	mod.read( YPTR, actualY );
	viewY = new Float32Array( actualY.buffer );
	isApprox( t, viewY, ye, 10.0 );

	t.end();
});

tape( 'a module instance has a `main` method which supports an `x` stride', function test( t ) {
	var actualY;
	var viewY;
	var mem;
	var mod;
	var ye;

	mem = new Memory({
		'initial': 1
	});
	mod = new Module( mem );
	mod.initializeSync();

	mod.write( XPTR, new Complex64Array( [ 0.7, -0.8, -0.4, -0.7, -0.1, -0.9, 0.2, -0.8, -0.9, -0.4, 0.1, 0.4, -0.6, 0.6 ] ) );
	mod.write( YPTR, new Complex64Array( [ 0.6, -0.6, -0.9, 0.5, 0.7, -0.6, 0.1, -0.5, -0.1, -0.2, -0.5, -0.3, 0.8, -0.7 ] ) );
	mod.write( APTR, new Float32Array( [ 0.4, -0.7 ] ) );

	ye = new Float32Array([
		0.32, -1.41, -1.57, 0.21, 0.06, -0.13, 0.28, 0.16, -0.1, -0.2, -0.5, -0.3, 0.8, -0.7
	]);

	mod.main( 4, APTR, XPTR, 2, YPTR, 1 );

	actualY = new Complex64Array( 7 );
	mod.read( YPTR, actualY );
	viewY = new Float32Array( actualY.buffer );
	isApprox( t, viewY, ye, 10.0 );

	t.end();
});

